    out = bytearray()
    for x in samples:
        v = max(0, min(0xFFFF, x))
        out += struct.pack('<H', v)
    return bytes(out)

def pack_i16(samples: List[int]) -> bytes:
    out = bytearray()
    for x in samples:
        v = max(-32768, min(32767, x))
        out += struct.pack('<h', v)
    return bytes(out)

def pack_f32(samples: List[float]) -> bytes:
    out = bytearray()
    for x in samples:
        out += struct.pack('<f', float(x))
    return bytes(out)

# Waveform constructors

def sine_wave(n: int, freq_bins: List[int], sample_rate: float, amp: float = 0.8) -> List[float]:
    # Build multi-sine waveform in [-1,1]
    res = []
    # avoid division by zero
    sr = max(1.0, sample_rate)
    for i in range(n):
        t = i / sr
        v = 0.0
        for fb in freq_bins:
            freq = max(1.0, float(fb))  # treat as Hz here; fuzz bins mapped to low Hz range
            v += math.sin(2.0 * math.pi * freq * t)
        if freq_bins:
            v /= float(len(freq_bins))
        res.append(max(-1.0, min(1.0, v * amp)))
    return res

def tone_burst(n: int, freq: float, sample_rate: float) -> List[float]:
    # Hann windowed burst
    out = []
    for i in range(n):
        w = 0.5 - 0.5 * math.cos(2.0 * math.pi * i / max(1, n - 1))
        out.append(w * math.sin(2.0 * math.pi * freq * (i / max(1.0, sample_rate))))
    return out

def noise(n: int, amp: float, rnd: random.Random) -> List[float]:
    return [amp * (2.0 * rnd.random() - 1.0) for _ in range(n)]

def clamp_float_to_i16(x: float) -> int:
    return int(max(-32768, min(32767, round(x * 32767.0))))

def to_format(fmt: str, floats: List[float], rnd: random.Random) -> bytes:
    # Map normalized [-1,1] floats into requested format
    if fmt == 'u8':
        ints = [int(max(0, min(255, round((x * 0.5 + 0.5) * 255.0)))) for x in floats]
        return pack_u8(ints)
    if fmt == 'i8':
        ints = [int(max(-128, min(127, round(x * 127.0)))) for x in floats]
        return pack_i8(ints)
    if fmt == 'u16':
        ints = [int(max(0, min(65535, round((x * 0.5 + 0.5) * 65535.0)))) for x in floats]
        return pack_u16(ints)
    if fmt == 'i16':
        ints = [clamp_float_to_i16(x) for x in floats]
        return pack_i16(ints)
    if fmt == 'f32':
        # Some values within [-1,1], some larger to exercise filter/FFT dynamics
        vals = []
        for v in floats:
            if rnd.random() < 0.1:
                v *= (1.0 + 4.0 * rnd.random())
            vals.append(v)
        return pack_f32(vals)
    # default
    return pack_i16([clamp_float_to_i16(x) for x in floats])

# Build different classes of buffers expected by stubs

def build_payload(rnd: random.Random) -> bytes:
    # Valid payload for encode/init, length 0..256
    modes = [
        'empty', 'short_ascii', 'random_bin', 'repeating', 'structured', 'max']
    mode = rnd.choice(modes)
    if mode == 'empty':
        size = 0
        return bytes()
    if mode == 'short_ascii':
        s = rnd.choice([
            'Hello GGWave', 'Test', 'Ping', 'こんにちは', '😀 UTF-8', '1234567890'])
        b = s.encode('utf-8')
        return b[:MAX_PAYLOAD]
    if mode == 'random_bin':
        size = rnd.randint(1, MAX_PAYLOAD)
        return bytes(rnd.getrandbits(8) for _ in range(size))
    if mode == 'repeating':
        pat_len = rnd.randint(1, 8)
        pat = bytes(rnd.getrandbits(8) for _ in range(pat_len))
        size = rnd.randint(1, MAX_PAYLOAD)
        return (pat * (size // len(pat) + 1))[:size]
    if mode == 'structured':
        # Include bytes 0..255, then slice
        base = bytes(range(256))
        size = rnd.randint(1, MAX_PAYLOAD)
        off = rnd.randint(0, max(0, len(base) - size))
        return base[off:off + size]
    if mode == 'max':
        return bytes(rnd.getrandbits(8) for _ in range(MAX_PAYLOAD))
    return bytes()

def build_waveform_bytes(rnd: random.Random) -> bytes:
    # Produce plausible audio buffers that the decoder and helpers accept.
    # Choose sample format and size consistent with stubs (<=2048 bytes, non-empty)
    fmt = rnd.choice(['i16', 'u8', 'f32', 'i8', 'u16'])
    # Choose a target byte length that aligns with sample size for the fmt
    bps = {'u8': 1, 'i8': 1, 'u16': 2, 'i16': 2, 'f32': 4}[fmt]
    max_samps = max(1, MAX_BYTES // bps)
    n_samples = rnd.randint(8, min(1024, max_samps))

    # Choose a content profile
    profile = rnd.choice(['sine', 'multisine', 'burst', 'noise', 'mixed'])
    sr = rnd.choice([8000.0, 11025.0, 16000.0, 22050.0, 32000.0, 44100.0, 48000.0])

    floats: List[float]
    if profile == 'sine':
        f = rnd.uniform(200.0, min(4000.0, 0.4 * sr))
        floats = sine_wave(n_samples, [int(f)], sr, amp=0.9)
    elif profile == 'multisine':
        ntones = rnd.randint(2, 6)
        freqs = [int(rnd.uniform(150.0, min(6000.0, 0.45 * sr))) for _ in range(ntones)]
        floats = sine_wave(n_samples, freqs, sr, amp=0.7)
    elif profile == 'burst':
        f = rnd.uniform(300.0, min(6000.0, 0.45 * sr))
        floats = tone_burst(n_samples, f, sr)
    elif profile == 'noise':
        floats = noise(n_samples, amp=rnd.uniform(0.05, 0.9), rnd=rnd)
    else:  # mixed
        f = rnd.uniform(300.0, min(6000.0, 0.45 * sr))
        floats = tone_burst(n_samples, f, sr)
        # add a bit of noise
        for i in range(n_samples):
            floats[i] = max(-1.0, min(1.0, floats[i] + rnd.uniform(-0.1, 0.1)))

    data = to_format(fmt, floats, rnd)
    # Ensure non-empty and <= 2048 bytes; trim if needed
    if not data:
        data = b"\x00"
    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]
    return data

def build_fft_blob(rnd: random.Random) -> bytes:
    # Some paths memcpy fuzz string into float arrays for FFT/filter/resampler.
    # Provide a float32 blob with recognizable patterns and sufficient size.
    N = rnd.randint(16, 512)
    # Build a simple ramp + noise pattern in float32
    arr = [(i / float(N)) + 0.05 * (2.0 * rnd.random() - 1.0) for i in range(N)]
    return pack_f32(arr)[:MAX_BYTES]

def build_filter_blob(rnd: random.Random) -> bytes:
    # Waveform for filter: float32 preferred, with windowed content
    N = rnd.randint(32, 1024)
    sr = rnd.choice([16000.0, 22050.0, 32000.0, 44100.0, 48000.0])
    f = rnd.uniform(100.0, min(5000.0, 0.45 * sr))
    floats = tone_burst(N, f, sr)
    return to_format('f32', floats, rnd)[:MAX_BYTES]

# Strategy selection for a given seed call:
# - Bias towards waveform-like buffers to assist decode and helpers
# - Sometimes produce payload-like buffers to feed encode/init
# - Occasionally produce structured float32 blobs for FFT/filter

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    choice = rnd.random()
    if choice < 0.5:
        # Decoder-heavy paths benefit from realistic waveforms
        return build_waveform_bytes(rnd)
    elif choice < 0.75:
        # Payload for encode/init
        return build_payload(rnd)
    else:
        # Helper routines expect float32 content frequently
        if rnd.random() < 0.5:
            return build_fft_blob(rnd)
        else:
            return build_filter_blob(rnd)
